diagrams.data:
graph TB;
    A[第1層: 対象認識] --> B[第2層: 認識の監視];
    B --> C[第3層: 監視の評価];
    C --> D{ワーキングメモリ限界};
    D -->|キャッシュミス| E[コンテキスト喪失];
    D -->|フォールバック| F[直感による結論の捏造];
    E --> G((スタックオーバーフロー));
    F --> G;
    style A fill:#dfd,stroke:#333;
    style G fill:#f66,stroke:#333,stroke-width:2px;
